-- Cloudflare D1 schema planned for persistent workspaces
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL DEFAULT 'student',license_status TEXT NOT NULL DEFAULT 'active',license_expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',retention_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,channel TEXT NOT NULL,network TEXT NOT NULL,operation_type TEXT NOT NULL,amount_cents INTEGER NOT NULL,currency TEXT NOT NULL,response_code TEXT,status TEXT,stan TEXT,rrn TEXT,auth_code TEXT,batch_number INTEGER,closed INTEGER NOT NULL DEFAULT 0,clearing_status TEXT NOT NULL DEFAULT 'PENDING',request_mti TEXT,response_mti TEXT,pan_last4 TEXT,created_at TEXT NOT NULL,FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS batches (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,channel TEXT NOT NULL,batch_number INTEGER NOT NULL,status TEXT NOT NULL,request_mti TEXT,response_mti TEXT,response_code TEXT,count INTEGER NOT NULL,total_cents INTEGER NOT NULL,closed_at TEXT NOT NULL,FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS clearing_artifacts (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,artifact_type TEXT NOT NULL,status TEXT NOT NULL,object_key TEXT,count INTEGER,total_cents INTEGER,created_at TEXT NOT NULL,FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE INDEX IF NOT EXISTS idx_tx_workspace ON transactions(workspace_id,created_at);
CREATE INDEX IF NOT EXISTS idx_tx_clearing ON transactions(workspace_id,clearing_status);
